import{B as e,Q as t,s as n,z as r}from"./chunks/framework.3ZETo7pw.js";var i=JSON.parse(`{"title":"Authentication Controllers","description":"","frontmatter":{},"headers":[],"relativePath":"backend/controllers/auth.md","filePath":"backend/controllers/auth.md"}`),a={name:`backend/controllers/auth.md`};function o(n,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[e(`<h1 id="authentication-controllers" tabindex="-1">Authentication Controllers <a class="header-anchor" href="#authentication-controllers" aria-label="Permalink to &quot;Authentication Controllers&quot;">​</a></h1><p>These controllers are primarily boilerplate generated by Laravel Breeze or Jetstream, handling the standard authentication lifecycle.</p><h2 id="controllers" tabindex="-1">Controllers <a class="header-anchor" href="#controllers" aria-label="Permalink to &quot;Controllers&quot;">​</a></h2><ul><li><code>AuthenticatedSessionController.php</code>: Handles logging in and out. Validates credentials and regenerates the session token.</li><li><code>RegisteredUserController.php</code>: Handles new user registration (if public registration is enabled). Hashes passwords and creates the <code>User</code> model.</li><li><code>PasswordResetLinkController.php</code> &amp; <code>NewPasswordController.php</code>: Manage the &quot;Forgot Password&quot; flow via email links.</li><li><code>VerifyEmailController.php</code> &amp; <code>EmailVerificationPromptController.php</code> &amp; <code>EmailVerificationNotificationController.php</code>: Handle email verification steps after registration.</li><li><code>ConfirmablePasswordController.php</code>: Requires the user to re-enter their password for sensitive actions.</li></ul><h2 id="context-for-ai-agents" tabindex="-1">Context for AI Agents <a class="header-anchor" href="#context-for-ai-agents" aria-label="Permalink to &quot;Context for AI Agents&quot;">​</a></h2><p>When modifying auth logic, agents should rarely touch these files unless adding new fields to the registration form or modifying the post-login redirect path.</p>`,6)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};